Translate("deDE", "darnassus", {
	title = "Darnassus",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Darnassus ist die {link:capital-city}Hauptstadt{/link} der {link:night-elves}Nachtelfen{/link}, eine Stadt aus lebendem Holz und mondbeschienenem Wasser in den hohen Ästen von {link:teldrassil}Teldrassil{/link}. Ihre Hallen sind gewachsen, nicht gebaut. Ihre Terrassen öffnen sich auf Gärten und stille Teiche, und der {link:temple-of-the-moon}Tempel des Mondes{/link} leuchtet in ihrem Herzen. Sie ist eine junge Stadt eines uralten Volkes. Die Kaldorei errichteten sie nach dem {link:third-war}Dritten Krieg{/link}, als sie ihre Unsterblichkeit verloren hatten und ihre alte Heimat auf dem {link:mount-hyjal}Berg Hyjal{/link} vernarbt dalag, und sie sollte ein neuer Anfang sein.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Als der Krieg gegen die {link:burning-legion}Brennende Legion{/link} vorüber war, ließen Erzdruide {link:fandral-staghelm}Fandral Staghelm{/link} und seine Druiden {link:teldrassil}Teldrassil{/link} vor der Nordküste wachsen. Darnassus erhob sich in seiner Krone. Die Priesterinnen der Elune bezogen dort ihren Tempel, die Druiden ihre Enklave und die {link:sentinels}Schildwachen{/link} ihre Kaserne. Von {link:rut-theran-village}Rut'theran{/link} tief unten trägt ein Portal Reisende hinauf in die Stadt.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Zwei Anführer haben ihren Sitz in Darnassus. {link:tyrande-whisperwind}Hohepriesterin Tyrande Whisperwind{/link} regiert die Stadt und ihr Volk nach dem Willen Elunes. {link:fandral-staghelm}Fandral Staghelm{/link} führt die Druiden in der langen Abwesenheit von {link:malfurion-stormrage}Malfurion Stormrage{/link}, der nicht aus dem {link:emerald-dream}Smaragdgrünen Traum{/link} zurückgekehrt ist. Tyrande bittet ihr Volk, seine Stellung zu achten, doch sie erinnert es daran, dass die Angelegenheiten von Darnassus allein die ihren sind. Fandral seinerseits traut niemandem außerhalb seiner Enklave. Er und {link:keeper-remulos}Bewahrer Remulos{/link} aus {link:moonglade}Moonglade{/link} verdächtigen einander der Hinterlist, und die Leiden des Weltbaums bleiben ungeheilt. Die {link:sentinels}Schildwachen{/link} halten innerhalb der Stadt selbst scharfe Wache, denn auf {link:teldrassil}Teldrassil{/link} stimmt etwas nicht.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die Priesterinnen der Elune.{/b} Sie pflegen den {link:temple-of-the-moon}Tempel des Mondes{/link} und heilen die Kaldorei.
• {b}Die Druiden des {link:cenarion-circle}Zirkels des Cenarius{/link}.{/b} Sie studieren in der {link:cenarion-enclave}Enklave des Cenarius{/link} unter dem Erzdruiden.
• {b}Die {link:sentinels}Schildwachen{/link}.{/b} Die Kriegerinnen, die die Stadt und die Wälder jenseits davon bewachen.
• {b}Verbündete der {link:alliance}Allianz{/link}.{/b} Zwergische Gelehrte der {link:explorers-league}Forscherliga{/link} und Gesandte der {link:argent-dawn}Argentumdämmerung{/link} sind in die Stadt gekommen.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die Gründung.{/b} Die Stadt wurde nach der {link:battle-of-mount-hyjal}Schlacht am Berg Hyjal{/link} in den Ästen des neuen Weltbaums errichtet.
• {b}Die Mondbrunnen.{/b} Die Druiden der Stadt schöpfen aus den Mondbrunnen von {link:teldrassil}Teldrassil{/link}, und Boten bringen Phiolen mit ihrem Wasser aus {link:shadowglen}Shadowglen{/link}, {link:dolanaar}Dolanaar{/link} und von der {link:the-oracle-glade}Lichtung des Orakels{/link} herauf.
• {b}Der Bruch mit {link:moonglade}Moonglade{/link}.{/b} Der Erzdruide und {link:keeper-remulos}Bewahrer Remulos{/link} haben sich voneinander entfernt, und die Druiden der Stadt dienen dem Zirkel unter einer Wolke des Misstrauens.
• {b}Die Gegenwart.{/b} Die Kaldorei sind der {link:alliance}Allianz{/link} beigetreten, und Helden aller Völker wandeln nun über die Terrassen von Darnassus.]=],
		},
		{
			title = "Überlieferungen der Stadt",
			text = [=[• Ein Brunnen im Herzen des Tempels des Mondes birgt heiliges Wasser, das alles reinigen soll, was es berührt.
• Der Baum des Erzdruiden steht in der {link:cenarion-enclave}Enklave des Cenarius{/link}, und unter ihm verlaufen Tunnel.
• Die Druiden von Darnassus untersuchen Erde, die aus dem fernen {link:un-goro-crater}Un'Goro-Krater{/link} gebracht wurde, und sie ziehen darin Kräuter, deren Natur sie noch nicht verstehen.]=],
		},
	},
})

Translate("deDE", "temple-of-the-moon", {
	title = "Tempel des Mondes",
	aliases = { "Tempelgärten", "Die Tempelgärten" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Tempel des Mondes steht inmitten der Tempelgärten im Süden von {link:darnassus}Darnassus{/link}. Er ist das Haus der Elune und der Sitz der Hohepriesterin. {link:tyrande-whisperwind}Tyrande Whisperwind{/link} hält in seiner oberen Halle Hof. Darunter unterweisen die Priesterinnen die Jungen und heilen die Verwundeten, und in seiner Mitte sprudelt ein Brunnen heiligen Wassers. Opfergaben, die in diesen Brunnen gelegt werden, werden der Göttin übergeben. {link:sentinels}Schildwachen{/link} bewachen seine Tore und beten dort täglich, denn eine Jägerin der Elune muss die Gaben ihrer Göttin ebenso gut führen wie ihre Klinge.]=],
		},
	},
})

Translate("deDE", "cenarion-enclave", {
	title = "Die Enklave des Cenarius",
	aliases = { "Enklave des Cenarius" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Enklave des Cenarius ist das Viertel der Druiden im Norden von {link:darnassus}Darnassus{/link}. Hier wächst der große Baum von {link:fandral-staghelm}Erzdruide Fandral Staghelm{/link}, in dem er zusammen mit seinem Stellvertreter {link:mathrengyl-bearwalker}Mathrengyl Bearwalker{/link}, ein Stockwerk tiefer, die Leiden von {link:teldrassil}Teldrassil{/link} erforscht. Druiden wie {link:rellian-greenspyre}Rellian Greenspyre{/link} wandeln auf ihren Pfaden. Auch Jäger und Schurken haben hier ihre Hallen. Hinter dem Baum des Erzdruiden warten Haufen seltsamer Erde aus fernen Landen darauf, sortiert zu werden, und Tunnel führen hinab in die Tiefen unter der Enklave.]=],
		},
	},
})

Translate("deDE", "warriors-terrace", {
	title = "Die Terrasse der Krieger",
	aliases = { "Terrasse der Krieger" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Terrasse der Krieger liegt im Osten von {link:darnassus}Darnassus{/link}. Hier üben sich die Krieger der Kaldorei unter Lehrmeistern wie Elanaria und Arias'ta Bladesinger, und hier führt die Kommandantin {link:thyn-tel-bladeweaver}Thyn'tel Bladeweaver{/link} die Angelegenheiten der {link:sentinels}Schildwachen{/link}. Die Habseligkeiten vermisster Schildwachen werden in ihrer Unterkunft verwahrt, bis sie zurückkehren. Eine Kriegerin, die mehr lernen will, muss zuerst ihre Entschlossenheit gegen die Feinde des Baumes beweisen.]=],
		},
	},
})

Translate("deDE", "craftsmens-terrace", {
	title = "Die Terrasse der Handwerker",
	aliases = { "Terrasse der Handwerker" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Terrasse der Handwerker liegt im Nordosten von {link:darnassus}Darnassus{/link}. Lederverarbeiter, Schneider und andere Handwerker der Kaldorei haben hier ihre Werkstätten, und das Gasthaus der Stadt bietet Reisenden aus allen Landen Rast. Gesandte der {link:argent-dawn}Argentumdämmerung{/link} haben sich zwischen den Handwerkern niedergelassen. Auch der Stoff der {link:alliance}Allianz{/link} wird hier gesammelt, für die Bedürfnisse des kommenden Krieges.]=],
		},
	},
})

Translate("deDE", "tradesmens-terrace", {
	title = "Die Terrasse der Händler",
	aliases = { "Terrasse der Händler" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Terrasse der Händler liegt im Osten von {link:darnassus}Darnassus{/link}, zwischen den Gärten und der {link:warriors-terrace}Terrasse der Krieger{/link}. Sie ist der Markt der Stadt. Händler für Speisen, Stoffe, Waffen und allerlei Waren haben ihre Stände entlang ihrer gewundenen Pfade, und Neuigkeiten aus dem Wald unten verbreiten sich rasch unter ihnen. Sie ist der geschäftigste Ort in Darnassus und doch stiller als jeder Markt in den Landen der {link:humans}Menschen{/link}.]=],
		},
	},
})

Translate("deDE", "tyrande-whisperwind", {
	title = "Tyrande Whisperwind",
	subtitle = "Hohepriesterin der Elune",
	found = "Die obere Halle des Tempels des Mondes",
	hint = [=[Steigt in die obere Halle des Tempels des Mondes hinauf und sucht die Hohepriesterin.]=],
	allegiance = "Nachtelfen · Schwesternschaft der Elune · Schildwachen",
	aliases = { "Tyrande", "Hohepriesterin Tyrande Whisperwind" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tyrande Whisperwind ist die Hohepriesterin der Elune und die Anführerin der {link:night-elves}Nachtelfen{/link}. Seit zehntausend Jahren behütet sie ihr Volk, zuerst in den Ruinen seines alten Imperiums und nun in den Ästen von {link:teldrassil}Teldrassil{/link}. Sie ist die Geliebte von {link:malfurion-stormrage}Malfurion Stormrage{/link}, und sie wartet auf seine Rückkehr. Sie regiert {link:darnassus}Darnassus{/link} mit fester Hand, und sie ist für ihre Güte bekannt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Tyrande ist das lebende Band zwischen den Kaldorei von einst und den Kaldorei von heute. Sie kämpfte im {link:war-of-the-ancients}Krieg der Ahnen{/link} und im {link:third-war}Dritten Krieg{/link}. Unter ihr wurden die {link:sentinels}Schildwachen{/link} zum Schild ihres Volkes, und unter ihr sind die {link:night-elves}Nachtelfen{/link} der {link:alliance}Allianz{/link} beigetreten.]=],
		},
		{
			title = "Geschichte",
			text = [=[Tyrande war eine Novizin der Schwesternschaft der Elune in den Tagen von {link:queen-azshara}Königin Azshara{/link}. Die Zwillingsbrüder {link:malfurion-stormrage}Malfurion{/link} und {link:illidan-stormrage}Illidan Stormrage{/link} liebten sie beide, und sie wählte Malfurion. Als die {link:burning-legion}Brennende Legion{/link} kam, kämpfte sie an ihrer Seite, und in jenem Krieg stieg sie zur Anführerin der Schwesternschaft auf. Nach der {link:great-sundering}Großen Teilung{/link}, während die Druiden im {link:emerald-dream}Smaragdgrünen Traum{/link} schliefen, hielten sie und ihre Priesterinnen lange Jahrhunderte hindurch Wache über die Wälder.

Als die Legion zurückkehrte und die {link:humans}Menschen{/link} und {link:orcs}Orcs{/link} nach {link:kalimdor}Kalimdor{/link} kamen, weckte Tyrande die schlafenden Druiden in ihren Grabhügeln. Sie befreite Illidan aus seinem Gefängnis, gegen den Willen ihres Geliebten. In der {link:battle-of-mount-hyjal}Schlacht am Berg Hyjal{/link} kämpften ihre {link:sentinels}Schildwachen{/link} an der Seite von Menschen und Orcs, bis {link:archimonde}Archimonde{/link} fiel.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[{link:malfurion-stormrage}Malfurion{/link} ist wieder in den Traum gegangen, und niemand weiß, was aus ihm geworden ist. Tyrande führt die Kaldorei allein. Sie achtet {link:fandral-staghelm}Fandral Staghelm{/link} als Erzdruiden, doch sie lässt ihn nicht vergessen, dass sein Bereich das Druidentum ist, während der ihre ihr ganzes Volk umfasst. Ihre Priesterinnen und {link:sentinels}Schildwachen{/link} bringen ihr Nachricht aus jedem Wald Kalimdors, und sie hört sie selbst an. Wer mit Taten für ihr Volk zu ihrem Tempel kommt, findet sie dankbar und großzügig, und schnell bittet sie darum, die Geschichten mit den Jungen zu teilen.]=],
		},
	},
	chapters = {
		{
			title = "Das Wasser der Mondbrunnen",
			hint = [=[Bringt der Hohepriesterin, was vom Wasser der Mondbrunnen geblieben ist.]=],
			text = [=[Die letzten Tropfen des Wassers der Mondbrunnen gelangten in einem zeremoniellen Gefäß zu Tyrande, nachdem der Erzdruide es beiseitegeworfen hatte. Sie dankte dem Überbringer, denn jeder Tropfen war von Elune gesegnet. Sie sprach auch, kurz und scharf, über {link:fandral-staghelm}Fandral{/link}: Er habe in Malfurions Abwesenheit viel getan, doch er sei nicht {link:malfurion-stormrage}Malfurion{/link}.]=],
		},
		{
			title = "Nachricht aus der Wildnis",
			hint = [=[Bringt der Hohepriesterin Nachricht von ihren Priesterinnen und Spähern in fernen Landen.]=],
			text = [=[Aus jedem Winkel Kalimdors erreichen Nachrichten den Tempel: von den {link:sentinels}Schildwachen{/link} im {link:stonetalon-mountains}Steinkrallengebirge{/link} und von der Priesterin {link:jer-kai-moonweaver}Jer'kai{/link}, die in {link:feralas}Feralas{/link} gegen {link:grimtotem-clan}die Grimmtotem{/link} kämpft. Tyrande hört jede Geschichte selbst an, und sie schickt ihre Späher, wohin sie gebraucht werden.]=],
		},
	},
	mentions = {
		{ text = "Empfang bei Tyrande" },
		{ text = "Gerechtigkeit üben" },
		{ text = "Die {link:alliance}Allianz{/link} erkunden" },
		{ text = "Die Krone der Erde" },
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "ihr Geliebter" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "der Bruder, den sie befreite" },
		{ id = "fandral-staghelm", name = "Fandral Staghelm", note = "Erzdruide ihres Volkes" },
		{ id = "sentinels", name = "Schildwachen", note = "ihre Wächterinnen" },
		{ id = "priestess-a-moora", name = "Priesterin A'moora", note = "dient in ihrem Tempel" },
	},
})

Translate("deDE", "fandral-staghelm", {
	title = "Fandral Staghelm",
	subtitle = "Erzdruide von Darnassus",
	found = "Sein Baum in der Enklave des Cenarius",
	hint = [=[Sucht den Erzdruiden in seinem Baum in der Enklave des Cenarius.]=],
	allegiance = "Nachtelfen · Zirkel des Cenarius",
	aliases = { "Fandral", "Erzdruide Fandral Staghelm" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Fandral Staghelm ist der Erzdruide der {link:night-elves}Nachtelfen{/link}. Als {link:malfurion-stormrage}Malfurion Stormrage{/link} nach dem {link:third-war}Dritten Krieg{/link} verschwand, übernahm Fandral die Führung der Druiden und beschloss, dass sein Volk wieder aufbauen würde. Er ließ {link:teldrassil}Teldrassil{/link} wachsen, den neuen Weltbaum, und er arbeitet noch immer daran, ihn heil zu machen. Er ist stolz, ungeduldig und unermüdlich, und er traut niemandem außer sich selbst zu, das Werk zu vollenden.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Nur wenige Kaldorei haben das gegenwärtige Zeitalter mehr geprägt als Fandral. {link:darnassus}Darnassus{/link} steht in dem Baum, den er wachsen ließ. Doch der Baum ist fehlerhaft, die Unsterblichkeit, die er suchte, ist nicht zurückgekehrt, und sein Streit mit {link:moonglade}Moonglade{/link} spaltet den {link:cenarion-circle}Zirkel des Cenarius{/link}.]=],
		},
		{
			title = "Geschichte",
			text = [=[Nach der {link:battle-of-mount-hyjal}Schlacht am Berg Hyjal{/link} lag {link:nordrassil}Nordrassil{/link} rauchend da, und die Druiden waren ohne Anführer. Fandral überzeugte den Zirkel der Uralten in der {link:darkshore}Dunkelküste{/link}, dass die Kaldorei wieder aufbauen und ihre Unsterblichkeit zurückgewinnen müssten. Mit der Zustimmung des Zirkels ließen er und die mächtigsten Druiden {link:teldrassil}Teldrassil{/link} vor der Nordküste wachsen. Dann bat er die Drachen um ihren Segen. Nozdormu verweigerte ihn und tadelte seine Überheblichkeit, und auch {link:alexstrasza}Alexstrasza{/link} verweigerte ihn. Ohne ihre Gaben ist der Baum fehlerhaft und unberechenbar gewachsen.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Fandral arbeitet ohne Rast an den Problemen des Baumes, und er nennt sie ein Joch, das er gern loswürde. Er glaubt, allein sein Volk aus der Dunkelheit geführt zu haben, und er nennt die Worte aus {link:moonglade}Moonglade{/link} Propaganda. {link:keeper-remulos}Bewahrer Remulos{/link} und er verdächtigen einander. Selbst sein eigener Stellvertreter gibt zu, dass die Luft zwischen ihnen dick vor Misstrauen ist.]=],
		},
		{
			title = "Taten",
			text = [=[• Er ließ {link:teldrassil}Teldrassil{/link} wachsen, den neuen Weltbaum.
• Er untersucht die Erde von {link:un-goro-crater}Un'Goro{/link} und das Kraut Morgenkorn.
• Er sendet Botschaften an {link:onu}Onu{/link}, den Uralten der Lehren in der {link:darkshore}Dunkelküste{/link}.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Wenig ist über Fandrals Leben vor dem Dritten Krieg geschrieben. Dieser Eintrag verzeichnet nur seine Taten seither.]=],
		},
	},
	chapters = {
		{
			title = "Die Krone der Erde",
			hint = [=[Bringt dem Erzdruiden das Wasser der Mondbrunnen von Teldrassil.]=],
			text = [=[Das Gefäß, gefüllt aus den Mondbrunnen des Baumes, erreichte Fandral endlich. Er murrte, es habe zu lange gedauert und die Boten seien nicht die zuverlässigsten. Dann sprach er von der Last der Probleme Teldrassils auf seinen Schultern.]=],
		},
		{
			title = "Der Bericht des Orakels",
			hint = "Überbringt dem Erzdruiden den Bericht des Orakelbaums.",
			text = [=[Der Orakelbaum hatte lange geschwiegen. Sein Bericht teilte Fandral mit, dass manche Leiden des Baumes nachgelassen hatten, während andere gewachsen waren. Er fürchtete laut, dass seine Arbeit nie getan sein würde.]=],
		},
		{
			title = "Die neue Grenze",
			hint = "Folgt dem Hilferuf des Zirkels des Cenarius.",
			text = [=[Als {link:moonglade}Moonglade{/link} im fernen Westen um Hilfe rief, übergab Fandral die Angelegenheit widerwillig an {link:mathrengyl-bearwalker}Mathrengyl{/link} und gab eine eigene Warnung dazu: kein Narr zu sein, der den Worten aus Moonglade glaubt.]=],
		},
	},
	mentions = {
		{ text = "Die Krone der Erde" },
		{ text = "{link:teldrassil}Teldrassil{/link}" },
		{ text = "{link:grove-of-the-ancients}Der Hain der Uralten{/link}" },
		{ text = "Die neue Grenze" },
		{ text = "Erde aus {link:un-goro-crater}Un'Goro{/link}" },
		{ text = "Erforschung des Morgenkorns" },
		{ text = "Wildekin der Elune" },
		{ text = "Die Krone der Erde, die Phiole, die er beiseitewarf" },
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "führt an seiner Stelle die Druiden" },
		{ id = "tyrande-whisperwind", name = "Tyrande Whisperwind", note = "regiert die Stadt, die er errichtete" },
		{ id = "mathrengyl-bearwalker", name = "Mathrengyl Bearwalker", note = "sein Stellvertreter" },
		{ id = "corithras-moonrage", name = "Corithras Moonrage", note = "sendet ihm das Wasser der Mondbrunnen" },
	},
})

Translate("deDE", "rellian-greenspyre", {
	title = "Rellian Greenspyre",
	subtitle = "Druide der Enklave des Cenarius",
	found = "Die Pfade der Enklave des Cenarius",
	hint = [=[Sucht den Druiden, der auf den Pfaden der Enklave des Cenarius wandelt.]=],
	allegiance = "Zirkel des Cenarius",
	aliases = { "Rellian" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Rellian Greenspyre ist ein Druide von {link:darnassus}Darnassus{/link} und ein Freund von {link:denalan}Denalan{/link} vom {link:lake-al-ameth}Al'Amethsee{/link}. Er hoffte, aus einem Samen einen Timberling zu ziehen, um die Arbeit seines Freundes zu unterstützen, doch er stellte fest, dass die Verderbnis vom Elternteil auf den Samen übergeht. Bis ein Heilmittel gefunden ist, sagt er, müssen die am stärksten befallenen Timberlinge gefällt und ihre Geschwüre verbrannt werden.]=],
		},
		{
			title = "Taten",
			text = [=[• Er erforscht die Verderbnis der Timberlinge.
• Er verbrennt die Geschwüre, die den Timberlingen am {link:wellspring-lake}Wellspringsee{/link} entnommen wurden.]=],
		},
	},
	mentions = {
		{ text = "Rellian Greenspyre" },
		{ text = "Geschwüre" },
		{ text = "Zurück zu {link:denalan}Denalan{/link}" },
	},
	bonds = {
		{ id = "denalan", name = "Denalan", note = "sein Freund" },
	},
})

Translate("deDE", "mathrengyl-bearwalker", {
	title = "Mathrengyl Bearwalker",
	subtitle = "Stellvertreter des Erzdruiden",
	found = "Das zweite Stockwerk des Baumes des Erzdruiden",
	hint = [=[Sucht den Stellvertreter des Erzdruiden ein Stockwerk unter ihm.]=],
	allegiance = "Zirkel des Cenarius",
	aliases = { "Mathrengyl" },
	sections = {
		{
			title = "Zusammenfassung",
