	},
})

Translate("deDE", "sentinels", {
	title = "Schildwachen",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Schildwachen sind die Krieger der {link:night-elves}Nachtelfen{/link}. Seit Tausenden von Jahren bewachen sie die Wälder von {link:kalimdor}Kalimdor{/link}, und sie unterstehen der Hohepriesterin der Elune. Die meisten sind Frauen, Jägerinnen, die die Gaben der Göttin ebenso führen wie die Gleve und den Bogen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Nach der {link:great-sundering}Großen Teilung{/link}, während die Druiden im {link:emerald-dream}Smaragdgrünen Traum{/link} schliefen, hielten die Priesterinnen der Elune und ihre Kriegerinnen Wache über die Kaldorei. In jenen langen Zeitaltern wurden die Schildwachen zum Schild ihres Volkes.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Schildwachen halten in jedem Dorf von {link:teldrassil}Teldrassil{/link} und an jeder Straße Wache. Sie bewachen den Orakelbaum, bringen seine Botschaften nach {link:darnassus}Darnassus{/link} und bekämpfen die {link:gnarlpine-furbolgs}Knarzklauen{/link} und die {link:harpies}Harpyien{/link}. Jenseits des Baumes halten sie Posten in der {link:darkshore}Dunkelküste{/link}, im {link:ashenvale}Eschental{/link} und in {link:feralas}Feralas{/link}. {link:shandris-feathermoon}General Feathermoon{/link} sorgt dafür, dass jede von ihnen Zeit zum Beten hat, und in Darnassus bewachen sie die Stadt selbst, denn sie fürchten, dass etwas nicht stimmt.]=],
		},
	},
})
